  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `semester` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '1st Semester, 2nd Semester, Summer',
  `academic_year` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'e.g., 2024-2025',
  `schedule_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'lecture' COMMENT 'lecture, lab, both',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
